-- Candidate only; same Pro submit function, whitespace-token AND within anchor OR.
DO $cas$
DECLARE old_oid oid; old_acl aclitem[]; old_config text[]; old_security boolean; old_owner oid; old_language oid; old_volatility char; old_parallel char; definition text;
BEGIN
 SELECT oid,proacl,proconfig,prosecdef,proowner,prolang,provolatile,proparallel INTO old_oid,old_acl,old_config,old_security,old_owner,old_language,old_volatility,old_parallel FROM pg_proc WHERE oid='public.crowd_v4_pro_submit(bigint,uuid,uuid,jsonb,uuid)'::regprocedure;
 definition:=pg_get_functiondef(old_oid);
 IF md5(definition)<>'8ad52b95b316eea0eefc27bf67bd5b9f' THEN RAISE EXCEPTION 'pro_anchor_function_drift'; END IF;
 IF old_acl::text IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' OR old_config IS DISTINCT FROM ARRAY['search_path=""']::text[] OR old_security IS DISTINCT FROM true OR pg_get_userbyid(old_owner)<>'postgres' THEN RAISE EXCEPTION 'pro_anchor_attributes_drift'; END IF;
 IF length(definition)-length(replace(definition,$old$not exists(select from jsonb_array_elements_text(t.anchor_terms)a(term) where length(term)>=2 and strpos(lower(regexp_replace((r->>'title')||' '||(r->>'body'),'[[:space:][:punct:]]','','g')),lower(regexp_replace(term,'[[:space:][:punct:]]','','g')))>0)$old$,''))<>length($old$not exists(select from jsonb_array_elements_text(t.anchor_terms)a(term) where length(term)>=2 and strpos(lower(regexp_replace((r->>'title')||' '||(r->>'body'),'[[:space:][:punct:]]','','g')),lower(regexp_replace(term,'[[:space:][:punct:]]','','g')))>0)$old$) THEN RAISE EXCEPTION 'pro_anchor_matcher_drift'; END IF;
 EXECUTE replace(definition,$old$not exists(select from jsonb_array_elements_text(t.anchor_terms)a(term) where length(term)>=2 and strpos(lower(regexp_replace((r->>'title')||' '||(r->>'body'),'[[:space:][:punct:]]','','g')),lower(regexp_replace(term,'[[:space:][:punct:]]','','g')))>0)$old$,$new$not exists(select from jsonb_array_elements_text(t.anchor_terms)a(term) where length(term)>=2 and not exists(select from regexp_split_to_table(regexp_replace(term,'^[[:space:]]+|[[:space:]]+$','','g'),'[[:space:]]+')w(token) where regexp_replace(token,'[[:space:][:punct:]]','','g')='' or strpos(lower(regexp_replace((r->>'title')||' '||(r->>'body'),'[[:space:][:punct:]]','','g')),lower(regexp_replace(token,'[[:space:][:punct:]]','','g')))=0))$new$);
 IF md5(pg_get_functiondef(old_oid))<>'515256f1e2f6ea99ca2ce419fe7961a8' OR NOT EXISTS(SELECT FROM pg_proc WHERE oid=old_oid AND proacl IS NOT DISTINCT FROM old_acl AND proconfig IS NOT DISTINCT FROM old_config AND prosecdef=old_security AND proowner=old_owner AND prolang=old_language AND provolatile=old_volatility AND proparallel=old_parallel) THEN RAISE EXCEPTION 'pro_anchor_postcondition'; END IF;
END $cas$;
